# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import List, Sequence, Tuple

from rosterkit.models import Student

def _check(students: Sequence[Student]) -> None:
    if not students:
        raise ValueError("no students to list")
    for student in students:
        if not (student.email or "").strip():
            name = student.display_name
            raise ValueError(f"no email for {name}")

def _cells(student: Student) -> Tuple[str, str, str]:
    name = student.display_name
    return (name, student.section, student.email.strip())

def _widths(rows: List[Tuple[str, ...]]) -> List[int]:
    cols = zip(*rows)
    return [max(len(cell) for cell in col) for col in cols]

def _format(cells: Sequence[str], widths: list) -> str:
    pairs = zip(cells, widths)
    line = "  ".join(c.ljust(w) for c, w in pairs)
    return line.rstrip()

# ---
def contact_rows(students: Sequence[Student]) -> List[str]:
    """Rows of name, section and email, sorted by name."""
    _check(students)
    key = lambda s: s.display_name.casefold()
    cells = [_cells(s) for s in sorted(students, key=key)]
    widths = _widths(cells)
    return [_format(row, widths) for row in cells]
